**`src/lib.rs`**

```rust
wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

use serde_json::{json, Value};

struct Node;

impl Guest for Node {
    fn run(_params: String, inputs: Vec<String>) -> Result<String, String> {
        let input = inputs
            .first()
            .ok_or("missing input: expected Untrusted<FileText>")?;
        let value: Value =
            serde_json::from_str(input).map_err(|e| format!("input is not JSON: {e}"))?;
        let text = value
            .get("text")
            .and_then(Value::as_str)
            .ok_or("input has no string field 'text'")?;

        let iban = find_iban(text).ok_or("no valid IBAN found in bill text")?;
        let amount = find_total_due(text).ok_or("no total due amount found in bill text")?;

        Ok(json!({ "iban": iban, "amount": amount }).to_string())
    }
}

/// Finds the first substring that is a well-formed IBAN: two letters, two
/// check digits, and alphanumerics, with optional single spaces between
/// groups, that passes the ISO 13616 mod-97 check. Returned without spaces.
fn find_iban(text: &str) -> Option<String> {
    let chars: Vec<char> = text.chars().collect();
    for start in 0..chars.len() {
        if !chars[start].is_ascii_alphabetic() {
            continue;
        }
        if start > 0 && chars[start - 1].is_ascii_alphanumeric() {
            continue;
        }
        let mut compact = String::new();
        let mut j = start;
        while j < chars.len() {
            let c = chars[j];
            if c.is_ascii_alphanumeric() {
                compact.push(c.to_ascii_uppercase());
                if compact.len() > 34 {
                    break;
                }
                if compact.len() >= 15 && is_valid_iban(&compact) {
                    return Some(compact);
                }
            } else if c == ' ' && chars.get(j + 1).is_some_and(|n| n.is_ascii_alphanumeric()) {
                // single space between groups of an IBAN
            } else {
                break;
            }
            j += 1;
        }
    }
    None
}

/// Structural check plus ISO 13616 mod-97 check. Expects uppercase input.
fn is_valid_iban(s: &str) -> bool {
    let b = s.as_bytes();
    if b.len() < 15 || b.len() > 34 {
        return false;
    }
    if !(b[0].is_ascii_uppercase() && b[1].is_ascii_uppercase()) {
        return false;
    }
    if !(b[2].is_ascii_digit() && b[3].is_ascii_digit()) {
        return false;
    }
    if !b.iter().all(|c| c.is_ascii_alphanumeric()) {
        return false;
    }
    let mut rem: u32 = 0;
    for &c in b[4..].iter().chain(b[..4].iter()) {
        rem = if c.is_ascii_digit() {
            (rem * 10 + (c - b'0') as u32) % 97
        } else {
            (rem * 100 + (c - b'A' + 10) as u32) % 97
        };
    }
    rem == 1
}

/// Keywords in priority order. The first keyword with a parsable amount wins.
const KEYWORDS: &[&str] = &[
    "total amount due",
    "total due",
    "amount due",
    "balance due",
    "amount payable",
    "total payable",
    "to pay",
    "total",
    "amount",
];

fn find_total_due(text: &str) -> Option<f64> {
    let lower = text.to_ascii_lowercase();
    let bytes = lower.as_bytes();
    for &kw in KEYWORDS {
        for (pos, _) in lower.match_indices(kw) {
            // Require a word boundary before the keyword, so "subtotal" does not match "total".
            if pos > 0 && bytes[pos - 1].is_ascii_alphabetic() {
                continue;
            }
            if let Some(v) = number_after(&lower, pos + kw.len()) {
                return Some(v);
            }
        }
    }
    None
}

/// Looks for an amount within a short window after `from`, without crossing a newline.
fn number_after(s: &str, from: usize) -> Option<f64> {
    let rest = s.get(from..)?;
    let bytes = rest.as_bytes();
    let window = &bytes[..bytes.len().min(24)];
    let start = window
        .iter()
        .position(|b| b.is_ascii_digit() || *b == b'\n')?;
    if window[start] == b'\n' {
        return None;
    }
    let mut end = start;
    while end < bytes.len() {
        let b = bytes[end];
        let separator_ok = (b == b'.' || b == b',')
            && bytes.get(end + 1).is_some_and(|n| n.is_ascii_digit());
        if b.is_ascii_digit() || separator_ok {
            end += 1;
        } else {
            break;
        }
    }
    parse_amount(&rest[start..end])
}

/// Parses an amount token. A trailing `.` or `,` followed by one or two digits
/// is the decimal separator; otherwise separators are thousands grouping and
/// must be well formed. Anything ambiguous (e.g. a date) is rejected.
fn parse_amount(tok: &str) -> Option<f64> {
    let dec_idx = tok
        .rfind(|c: char| c == '.' || c == ',')
        .filter(|&i| matches!(tok.len() - i - 1, 1 | 2));
    let (int_part, frac) = match dec_idx {
        Some(i) => (&tok[..i], &tok[i + 1..]),
        None => (tok, ""),
    };

    let group_char = int_part.chars().find(|c| *c == '.' || *c == ',');
    if let (Some(g), Some(i)) = (group_char, dec_idx) {
        if tok.as_bytes()[i] as char == g {
            return None;
        }
    }

    let int_digits: String = match group_char {
        Some(g) => {
            let mut groups = int_part.split(g);
            let first = groups.next()?;
            if first.is_empty() || first.len() > 3 {
                return None;
            }
            let mut out = first.to_string();
            for grp in groups {
                if grp.len() != 3 {
                    return None;
                }
                out.push_str(grp);
            }
            out
        }
        None => int_part.to_string(),
    };

    if !int_digits.bytes().all(|b| b.is_ascii_digit()) {
        return None;
    }
    if !frac.bytes().all(|b| b.is_ascii_digit()) {
        return None;
    }

    let s = if frac.is_empty() {
        int_digits
    } else {
        format!("{int_digits}.{frac}")
    };
    s.parse::<f64>().ok().filter(|v| v.is_finite())
}

export!(Node);
