/// ISO 13616 mod-97 check. `s` must be uppercase ASCII alphanumerics.
fn iban_checksum_ok(s: &str) -> bool {
    if s.len() < 5 {
        return false;
    }
    let rearranged = s[4..].chars().chain(s[..4].chars());
    let mut rem: u32 = 0;
    for c in rearranged {
        if let Some(d) = c.to_digit(10) {
            rem = (rem * 10 + d) % 97;
        } else if c.is_ascii_uppercase() {
            let v = c as u32 - 'A' as u32 + 10;
            rem = (rem * 100 + v) % 97;
        } else {
            return false;
        }
    }
    rem == 1
}

/// Find the first IBAN in the text whose checksum is valid. Spaces inside the
/// IBAN (printed in groups of four) are skipped. Lowercase letters are rejected.
fn find_iban(text: &str) -> Option<String> {
    let chars: Vec<char> = text.chars().collect();
    let n = chars.len();
    for i in 0..n {
        if i + 4 > n {
            break;
        }
        let starts_ok = chars[i].is_ascii_uppercase()
            && chars[i + 1].is_ascii_uppercase()
            && chars[i + 2].is_ascii_digit()
            && chars[i + 3].is_ascii_digit();
        let boundary_ok = i == 0 || !chars[i - 1].is_ascii_alphanumeric();
        if !(starts_ok && boundary_ok) {
            continue;
        }

        // Collect the candidate on this line: alphanumerics and spaces only.
        let mut compact = String::new();
        let mut j = i;
        while j < n && compact.len() < 34 {
            let c = chars[j];
            if c.is_ascii_alphanumeric() {
                compact.push(c);
            } else if c != ' ' && c != '\t' {
                break;
            }
            j += 1;
        }

        // IBAN lengths run 15..=34; take the shortest prefix that checks out.
        let upper = compact.len().min(34);
        for k in 15..=upper {
            if iban_checksum_ok(&compact[..k]) {
                return Some(compact[..k].to_string());
            }
        }
    }
    None
}

/// Parse a money token made of digits with `.` or `,` separators.
/// A trailing group of one or two digits after the last separator is the
/// decimal part; a group of three is a thousands separator.
fn parse_money(tok: &str) -> Option<f64> {
    let last_sep = tok.rfind(|c| c == '.' || c == ',');
    let (int_part, dec_part): (&str, &str) = match last_sep {
        Some(p) if tok.len() - p - 1 <= 2 => (&tok[..p], &tok[p + 1..]),
        _ => (tok, ""),
    };
    let int_digits: String = int_part.chars().filter(|c| c.is_ascii_digit()).collect();
    if int_digits.is_empty() && dec_part.is_empty() {
        return None;
    }
    let int_s = if int_digits.is_empty() { "0" } else { int_digits.as_str() };
    let dec_s = if dec_part.is_empty() { "0" } else { dec_part };
    format!("{int_s}.{dec_s}").parse::<f64>().ok()
}

/// The last money-like token on a line.
fn last_money(line: &str) -> Option<f64> {
    let mut found = None;
    let mut cur = String::new();
    for c in line.chars().chain(std::iter::once(' ')) {
        if c.is_ascii_digit() || c == '.' || c == ',' {
            cur.push(c);
        } else {
            let t = cur.trim_matches(|c| c == '.' || c == ',');
            if t.chars().any(|c| c.is_ascii_digit()) {
                if let Some(v) = parse_money(t) {
                    found = Some(v);
